import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Was brauche ich, bevor ich den Adapter installiere?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/01.voraussetzungen.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","filePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","lastUpdated":1795562976000}'),s={name:"de/adapter/esphome/erste-schritte/voraussetzungen.md"};function n(d,e,h,o,u,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="was-brauche-ich-bevor-ich-den-adapter-installiere" tabindex="-1">Was brauche ich, bevor ich den Adapter installiere? <a class="header-anchor" href="#was-brauche-ich-bevor-ich-den-adapter-installiere" aria-label="Permalink to &quot;Was brauche ich, bevor ich den Adapter installiere?&quot;">​</a></h1><p><a id="have-install-python-pip-myself"></a></p><h2 id="muss-ich-python-oder-pip-selbst-installieren" tabindex="-1">Muss ich Python oder pip selbst installieren? <a class="header-anchor" href="#muss-ich-python-oder-pip-selbst-installieren" aria-label="Permalink to &quot;Muss ich Python oder pip selbst installieren?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="systems-hardware-adapter-run"></a></p><h2 id="auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" tabindex="-1">Auf welchen Systemen und mit welcher Hardware läuft der Adapter? <a class="header-anchor" href="#auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" aria-label="Permalink to &quot;Auf welchen Systemen und mit welcher Hardware läuft der Adapter?&quot;">​</a></h2><p>Der Adapter läuft auf jedem System mit ioBroker und Node.js 22.12 oder neuer. Das integrierte ESPHome-Dashboard läuft nur auf 64-Bit-Linux und macOS.</p><table tabindex="0"><thead><tr><th>Was</th><th>Voraussetzung</th></tr></thead><tbody><tr><td>Adapter mit Geräten</td><td>Node.js 22.12 oder neuer, Admin 7.8.20 oder neuer, js-controller 6.0.11 oder neuer</td></tr><tr><td>Integriertes Dashboard</td><td>zusätzlich 64-Bit-Linux oder macOS und Internetzugang beim Start</td></tr><tr><td>Dashboard mit „Docker-Integration verwenden (Beta)“</td><td>zusätzlich Docker auf dem ioBroker-Rechner</td></tr></tbody></table><p>Für die Geräte braucht der Adapter kein Python, er spricht sie direkt über die Native API an. Python braucht nur das integrierte Dashboard. Der Adapter legt dafür beim Start eine eigene Umgebung an, standardmäßig mit Python 3.13.2.</p><p>Ein Raspberry Pi mit 64-Bit-Prozessor ist trotzdem ein 32-Bit-System, wenn das Betriebssystem in 32 Bit installiert ist. Dort startet das Dashboard erst nach einer Neuinstallation mit 64-Bit-Betriebssystem.</p><h3 id="welche-hardware-brauche-ich" tabindex="-1">Welche Hardware brauche ich? <a class="header-anchor" href="#welche-hardware-brauche-ich" aria-label="Permalink to &quot;Welche Hardware brauche ich?&quot;">​</a></h3><p>Für die Geräte reicht jede Hardware, auf der ioBroker läuft. Das Dashboard kompiliert Firmware, das braucht viel Rechenleistung und Arbeitsspeicher. Ein Raspberry Pi 3 wird dabei sehr langsam, ein Raspberry Pi 4 läuft stabil. Ist dein Rechner zu schwach oder läuft er unter Windows, betreibe das Dashboard auf einem anderen Rechner.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#use-external-esphome-dashboard-instead">Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten?</a></p><p><a id="need-home-assistant-mqtt-use"></a></p><h2 id="brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" tabindex="-1">Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen? <a class="header-anchor" href="#brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" aria-label="Permalink to &quot;Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',16)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
